insert into public.chapters (id, status, launched_on, lead_name, lead_photo, member_count, member_count_as_of, cover_image, is_flagship, is_published, slug, city, state, latitude, longitude, sort_order, intro) values
  ('00000000-0000-4000-8000-000000000010', 'active', null, null, null, null, null, '/photos/meetup-garden-room.webp', true, true, 'mumbai', 'Mumbai', 'Maharashtra', 19.076, 72.8777, 10, 'The city in the name, and home to BNC''s newest format: the Real Estate Room, an invite-only evening at Dextrus, Lower Parel, in October 2026 — 40 developers, investors and advisors around one question: where should we build and invest next?'),
  ('00000000-0000-4000-8000-000000000020', 'active', '2026-04-20', null, null, null, null, null, false, true, 'bangalore', 'Bangalore', 'Karnataka', 12.9716, 77.5946, 20, 'Opened in April 2026 with the Builder / Founder Mixer at BHIVE HSR: a curated 40-person room for founders, operators and creators who are actively building. 42 registered.'),
  ('00000000-0000-4000-8000-000000000030', 'active', '2025-12-06', null, null, null, null, '/media/events/career-connect-delhi-2026/group.webp', false, true, 'delhi-ncr', 'Delhi NCR', 'Delhi', 28.6139, 77.209, 30, 'One chapter across Delhi, Gurugram and Noida. Two rooms so far: a café meetup at Fika, Hauz Khas Village (39 registered), and Career Connect at Masters'' Union, Gurugram, with Re-Defined and Metvy (55 registered).'),
  ('00000000-0000-4000-8000-000000000040', 'active', '2025-09-20', null, null, null, null, '/media/events/pune-meetup-2025-09/group.webp', false, true, 'pune', 'Pune', 'Maharashtra', 18.5204, 73.8567, 40, 'BNC''s most active chapter, and the first room on its calendar (September 2025). Since then: breakfast meetups, a vision-board morning, ice-bath resets, a pitch-under-pressure challenge, Let''s Talk AI and the online Power Hour.'),
  ('00000000-0000-4000-8000-000000000050', 'active', '2025-10-05', null, null, null, null, null, false, true, 'hyderabad', 'Hyderabad', 'Telangana', 17.385, 78.4867, 50, 'Opened on 5 October 2025 with a café meetup at Third Wave Coffee, Banjara Hills, presented with Thirdspace. It filled to its last few seats.'),
  ('00000000-0000-4000-8000-000000000060', 'active', '2026-03-07', null, null, null, null, null, false, true, 'ahmedabad', 'Ahmedabad', 'Gujarat', 23.0225, 72.5714, 60, 'Opened in March 2026 at K''s Charcoal, Thaltej, with CA Shubham Maloo and Sumit Sengar. 208 people registered for 30 seats — the most selective BNC room yet.'),
  ('00000000-0000-4000-8000-000000000070', 'active', '2025-10-12', null, null, null, null, '/media/events/nashik-meetup-2025-10/room.webp', false, true, 'nashik', 'Nashik', 'Maharashtra', 19.9975, 73.7898, 70, 'Proof that founder rooms aren''t only for metros. Opened in October 2025 at Four Lost Cats, College Road — no panels, just conversations.'),
  ('00000000-0000-4000-8000-000000000080', 'active', '2025-11-09', null, null, null, null, null, false, true, 'surat', 'Surat', 'Gujarat', 21.1702, 72.8311, 80, 'Opened in November 2025 at ELK Espresso, Vesu, with LinkedIn creator CA Meher Kaur. Theme: not your regular networking.')
insert into public.events (id, summary, ends_at, venue, venue_address, luma_url, cover_image, capacity, who_attends, agenda, price_inr, registrations, is_online, poster, speakers, partners, gallery, is_published, slug, chapter_id, title, starts_at, format) values
  ('00000000-0000-4000-9000-000000000001', 'The first room on BNC''s calendar: an intimate, high-energy café meetup on networking, LinkedIn and personal brand, with practical strategies you can use the same week.', '2025-09-20T12:30:00.000Z', 'Mauji — The Time Cafe', 'Sahajeevan Society, ICS Colony, Bhoslenagar, Pune', 'https://luma.com/roc1c6gy', 'https://images.lumacdn.com/event-covers/3g/52c9eabc-d26a-4648-a702-d9be916c9aa0.jpg', 40, 'Entrepreneurs, freelancers, creators and professionals who want to grow their network and personal brand.', null, 499, 36, false, null, '[{"name":"Isha Ostwal","role":"Founder & CEO, DreamSVin · Networking strategist"},{"name":"Yogesh Agarwal","role":"CEO, Revamp Tribe · LinkedIn and personal-branding strategist"}]'::jsonb, null, '[{"src":"/media/events/pune-meetup-2025-09/group.webp","width":864,"height":484,"alt":"Members of the Pune meetup photographed together in a café garden under string lights."},{"src":"/media/events/pune-meetup-2025-09/talk.webp","width":461,"height":430,"alt":"The host speaking to the room at the Pune meetup."},{"src":"/media/events/pune-meetup-2025-09/circle.webp","width":578,"height":564,"alt":"Members seated in a circle under a yellow canopy, listening to the host at the Pune meetup."},{"src":"/media/events/pune-meetup-2025-09/hosts.webp","width":537,"height":631,"alt":"The hosts welcome members in the café garden at the Pune meetup."},{"src":"/media/events/pune-meetup-2025-09/chat.webp","width":491,"height":489,"alt":"Two members in conversation at the Pune meetup."},{"src":"/media/events/pune-meetup-2025-09/intros.webp","width":467,"height":496,"alt":"Members comparing notes during the guided networking round at the Pune meetup."},{"src":"/media/events/pune-meetup-2025-09/listening.webp","width":442,"height":622,"alt":"A member takes notes during the insights session at the Pune meetup."}]'::jsonb, true, 'pune-meetup-2025-09', '00000000-0000-4000-8000-000000000040', 'Bombay Networking Circle — Pune', '2025-09-20T10:30:00.000Z', 'founder_networking'),
  ('00000000-0000-4000-9000-000000000002', 'BNC''s first Hyderabad room: a café meetup in Banjara Hills, presented with Thirdspace. It filled to its last few seats.', '2025-10-05T12:30:00.000Z', 'Third Wave Coffee', 'Road No. 12, Banjara Hills, Hyderabad', 'https://luma.com/doricbbp', 'https://images.lumacdn.com/event-covers/7r/ce4c8a85-cd54-40c5-931e-a2b9ba83da68.jpg', null, null, null, null, 19, false, '/media/posters/hyderabad-2025-10.webp', null, '[{"name":"Thirdspace","role":"Presenting partner"}]'::jsonb, null, true, 'hyderabad-meetup-2025-10', '00000000-0000-4000-8000-000000000050', 'Bombay Networking Circle — Hyderabad', '2025-10-05T10:30:00.000Z', 'founder_networking'),
  ('00000000-0000-4000-9000-000000000003', 'No panels, just conversations. A café room on College Road for Nashik''s founders and builders — scale faster, together.', '2025-10-12T12:30:00.000Z', 'Four Lost Cats', 'Gangapur Road, D. K. Nagar, Nashik', 'https://luma.com/5kdf69xg', 'https://images.lumacdn.com/event-covers/8l/8c7fac4d-40e8-4761-99a4-204ddc91901a.jpg', 40, null, null, 499, 21, false, '/media/posters/nashik-2025-10.webp', null, null, '[{"src":"/media/events/nashik-meetup-2025-10/room.webp","width":805,"height":556,"alt":"The full room at the Nashik meetup, standing behind round white café tables."},{"src":"/media/events/nashik-meetup-2025-10/members.webp","width":751,"height":750,"alt":"Six members of the Nashik meetup smiling together."},{"src":"/media/events/nashik-meetup-2025-10/seated.webp","width":489,"height":483,"alt":"Members seated at café tables during the Nashik meetup."},{"src":"/media/events/nashik-meetup-2025-10/tables.webp","width":427,"height":670,"alt":"Members in conversation around café tables at the Nashik meetup."},{"src":"/media/events/nashik-meetup-2025-10/lounge.webp","width":470,"height":491,"alt":"Members talking in a café lounge with round mirrored alcoves."},{"src":"/media/events/nashik-meetup-2025-10/group.webp","width":910,"height":432,"alt":"A group photo of the Nashik meetup room."}]'::jsonb, true, 'nashik-meetup-2025-10', '00000000-0000-4000-8000-000000000070', 'Bombay Networking Circle — Nashik', '2025-10-12T10:30:00.000Z', 'founder_networking'),
  ('00000000-0000-4000-9000-000000000004', 'A Saturday-morning Pune meetup over coffee and breakfast on Law College Road.', null, 'Crazy Cheesy', 'Law College Road, Pune', null, null, null, null, null, null, null, false, '/media/posters/pune-2025-10.webp', null, null, null, true, 'pune-breakfast-meetup-2025-10', '00000000-0000-4000-8000-000000000040', 'Networking & conversations over coffee and breakfast — Pune', '2025-10-25T05:30:00.000Z', 'founder_networking'),
  ('00000000-0000-4000-9000-000000000005', 'Theme: not your regular networking. Surat''s first BNC room, with LinkedIn creator CA Meher Kaur.', '2025-11-09T12:30:00.000Z', 'ELK Espresso', 'Homeland City, Vesu, Surat', 'https://luma.com/d5mdgz69', 'https://images.lumacdn.com/event-covers/3v/8fc01abc-4246-42bd-bbee-bcbe2bcb08c2.jpg', 35, null, null, 499, 10, false, '/media/posters/surat-2025-11.webp', '[{"name":"Isha Ostwal","role":"Founder & CEO, DreamSVin · Networking strategist"},{"name":"CA Meher Kaur","role":"Founder, CreateUS.club · LinkedIn creator"}]'::jsonb, null, null, true, 'surat-edition-2025-11', '00000000-0000-4000-8000-000000000080', 'Bombay Networking Circle — Surat Edition', '2025-11-09T10:30:00.000Z', 'founder_networking'),
  ('00000000-0000-4000-9000-000000000006', 'An intimate, casual but high-energy café meetup in Hauz Khas Village. Real conversations, practical networking strategies, a curated room.', '2025-12-06T12:30:00.000Z', 'Fika Coffee Co.', 'Hauz Khas Village, New Delhi', 'https://luma.com/s9435s05', 'https://images.lumacdn.com/event-covers/j4/8edff0e5-9e4d-4635-8416-210bd93b8061.jpg', 40, null, null, 499, 39, false, null, '[{"name":"Isha Ostwal","role":"Founder & CEO, DreamSVin · Networking strategist"}]'::jsonb, null, null, true, 'delhi-meetup-2025-12', '00000000-0000-4000-8000-000000000030', 'Bombay Networking Circle — Delhi', '2025-12-06T10:30:00.000Z', 'founder_networking'),
  ('00000000-0000-4000-9000-000000000007', 'A cosy morning to design your 2026: a guided goal-setting reflection, vision-board materials, coffee and 20–30 people worth knowing.', '2025-12-28T06:00:00.000Z', 'Zariya Mind & Body Studio', 'NIBM Road, Undri, Pune', 'https://luma.com/38vbsg3d', 'https://images.lumacdn.com/event-covers/tf/02d2165c-a0eb-4ed0-aecc-149400fd3ced.jpg', 40, null, null, 699, 9, false, null, '[{"name":"Isha Ostwal","role":"Host"},{"name":"Raksha Agarwal","role":"Host"}]'::jsonb, null, null, true, 'pune-vision-board-2025-12', '00000000-0000-4000-8000-000000000040', 'Vision Board Over Coffee — Pune', '2025-12-28T04:30:00.000Z', 'workshop'),
  ('00000000-0000-4000-9000-000000000008', 'Cracking roles in startups and careers in entrepreneurship. Part of Ritika Saraswat''s Own Your Path India Tour 2026, hosted by BNC with Re-Defined and Metvy at Masters'' Union.', '2026-01-10T07:30:00.000Z', 'Masters'' Union School of Business', 'Udyog Vihar Phase II, Sector 20, Gurugram', 'https://luma.com/6yr6h85q', 'https://images.lumacdn.com/event-covers/dz/17f24f22-76ab-4105-92c6-d7541974a18c.jpg', null, 'Students, early-career professionals, founders, freelancers and creators navigating startup careers.', null, null, 55, false, null, '[{"name":"Isha Ostwal","role":"Host · Founder, DreamSVin & BNC"},{"name":"Ritika Saraswat","role":"Founder, Re-Defined"},{"name":"Shawrya","role":"Co-founder & COO, Metvy"}]'::jsonb, '[{"name":"Re-Defined","role":"Collaborator"},{"name":"Metvy","role":"Collaborator"},{"name":"Masters'' Union","role":"Venue"}]'::jsonb, '[{"src":"/media/events/career-connect-delhi-2026/group.webp","width":1600,"height":1200,"alt":"The full room at Career Connect – Delhi, Masters'' Union, Gurugram: about forty members standing together around a long table."},{"src":"/media/events/career-connect-delhi-2026/circle.webp","width":1600,"height":1200,"alt":"The hosts and guest mentors talking with the room at Career Connect – Delhi."},{"src":"/media/events/career-connect-delhi-2026/host.webp","width":1000,"height":1120,"alt":"The host, in red, listening to a question at Career Connect – Delhi."},{"src":"/media/events/career-connect-delhi-2026/panel.webp","width":1400,"height":1050,"alt":"A three-person panel on stage at Masters'' Union, Gurugram, with speaker slides on the screen behind."},{"src":"/media/events/career-connect-delhi-2026/room.webp","width":1600,"height":1200,"alt":"Members seated around a long conference table at Career Connect – Delhi, listening to the hosts."},{"src":"/media/events/career-connect-delhi-2026/mentor.webp","width":1000,"height":1133,"alt":"A guest mentor speaking to members at Career Connect – Delhi."},{"src":"/media/events/career-connect-delhi-2026/talk.webp","width":1400,"height":1050,"alt":"Hosts standing in front of the room during the open conversation at Career Connect – Delhi."},{"src":"/media/events/career-connect-delhi-2026/conversation.webp","width":1000,"height":1120,"alt":"Two members in conversation at Career Connect – Delhi."},{"src":"/media/events/career-connect-delhi-2026/qna.webp","width":1400,"height":1050,"alt":"A guest mentor answers a question from the room at Career Connect – Delhi."}]'::jsonb, true, 'career-connect-delhi-2026', '00000000-0000-4000-8000-000000000030', 'Career Connect — Delhi', '2026-01-10T05:30:00.000Z', 'career'),
  ('00000000-0000-4000-9000-000000000009', 'A structured, outcome-focused two hours: a strategic insights session, guided networking and an open collaboration round. 208 people registered for 30 seats.', '2026-03-07T12:30:00.000Z', 'K''s Charcoal', 'Sindhu Bhavan Marg, Thaltej, Ahmedabad', 'https://luma.com/6gjk0sdv', 'https://images.lumacdn.com/event-covers/mm/a0038997-c3ba-4ab8-b96b-c8ddad5885c1.png', null, 'Founders, creators, consultants and growth-driven professionals.', '[{"time":"45–60 min","item":"Strategic insights: relationships that convert, LinkedIn and offline visibility, positioning"},{"time":"30–40 min","item":"Guided networking: curated introductions, small-group exchanges"},{"time":"30–40 min","item":"Open collaboration round: what you''re building, partnerships, Q&A"}]'::jsonb, 499, 30, false, null, '[{"name":"Isha Ostwal","role":"Founder & CEO, DreamSVin · Networking strategist"},{"name":"Shubham Maloo","role":"CA · Startup and GST consultant"},{"name":"Sumit Sengar","role":"Founder, AUM Trading Institute"}]'::jsonb, '[{"name":"K''s Charcoal","role":"Venue partner"}]'::jsonb, null, true, 'ahmedabad-edition-2026-03', '00000000-0000-4000-8000-000000000060', 'Bombay Networking Circle — Ahmedabad Edition', '2026-03-07T10:30:00.000Z', 'founder_networking'),
  ('00000000-0000-4000-9000-000000000010', 'A curated 40-person builders'' room for founders, operators and creators who are actively building. Partnerships, hiring, distribution and strategic introductions.', '2026-04-20T15:30:00.000Z', 'BHIVE HSR Lounge', '22nd A Main Road, HSR Layout Sector 2, Bengaluru', 'https://luma.com/efophlhn', 'https://images.lumacdn.com/event-covers/ls/407bc72c-fa70-472f-a2a8-87ad84aefcaa.png', 40, 'Founders building or scaling a startup, product, agency or business; operators in growth-stage companies; creators monetising an audience.', null, 799, 42, false, null, null, '[{"name":"BHIVE Workspace","role":"Venue partner"}]'::jsonb, null, true, 'bengaluru-builder-mixer-2026-04', '00000000-0000-4000-8000-000000000020', 'Bengaluru Builder / Founder Mixer', '2026-04-20T13:00:00.000Z', 'founder_networking'),
  ('00000000-0000-4000-9000-000000000011', 'A curated wellness and networking morning: yoga and breathwork, a facilitated ice bath, then protein and real conversation. Limited to 20–25 people.', '2026-05-10T05:30:00.000Z', 'Padel Haus Arena', 'Salunkhe Vihar, Wanwadi, Pune', 'https://luma.com/s5aexdki', 'https://images.lumacdn.com/event-covers/2r/a9375f78-29f3-419f-8b7b-118cc3a91694.png', null, 'Founders building seriously, long-term creators, and operators who care about health and ambition.', '[{"time":"45 min","item":"Yoga and guided breathwork"},{"time":"45–60 min","item":"Ice bath, in small facilitated groups"},{"time":"60 min","item":"Protein networking"}]'::jsonb, 999, 35, false, null, '[{"name":"Bhoomi Thakkar","role":"Sync Studio · Fitness partner"}]'::jsonb, '[{"name":"Pickle Haus","role":"Venue partner"},{"name":"Sync Studio","role":"Fitness partner"}]'::jsonb, null, true, 'pune-sunday-reset-2026-05', '00000000-0000-4000-8000-000000000040', 'Sunday Reset with BNC', '2026-05-10T02:30:00.000Z', 'wellness'),
  ('00000000-0000-4000-9000-000000000012', 'A slow Saturday morning for women building ambitious lives: matcha, pilates, breathwork, reflection and networking.', '2026-06-13T05:00:00.000Z', 'Ekoham Holistic Wellness', 'Veerbhadra Nagar, Baner, Pune', 'https://luma.com/aljbwmuj', 'https://images.lumacdn.com/uploads/dg/73753f96-1c3c-419f-a3b1-2abae2f06f9a.png', null, 'Women founders, working professionals, creators and entrepreneurs.', null, 999, 31, false, null, null, '[{"name":"Ekoham Holistic Wellness","role":"Venue"}]'::jsonb, null, true, 'pune-wellness-weekend-reset-2026-06', '00000000-0000-4000-8000-000000000040', 'Wellness Weekend Reset', '2026-06-13T03:00:00.000Z', 'wellness'),
  ('00000000-0000-4000-9000-000000000013', 'Understanding cash flow, the financial metrics that matter, warning signs to catch early, and making growth decisions with confidence.', '2026-06-24T14:00:00.000Z', 'Online (Zoom)', null, 'https://luma.com/6n64826q', 'https://images.lumacdn.com/uploads/ws/43d27114-6367-45ea-9fad-aadbcaaeb708.jpg', null, null, null, 0, 14, true, null, '[{"name":"Hooshang Bakht","role":"COO, Brego Business"}]'::jsonb, null, null, true, 'power-hour-cash-flow-2026-06', '00000000-0000-4000-8000-000000000040', 'BNC Power Hour: cash flow for founders', '2026-06-24T13:00:00.000Z', 'power_hour'),
  ('00000000-0000-4000-9000-000000000014', 'Can you pitch under pressure? Founders pitched their startups from inside an ice bath, in front of entrepreneurs, investors and mentors, for a ₹1,00,000 prize.', '2026-06-27T07:30:00.000Z', 'Ekoham Holistic Wellness', 'Veerbhadra Nagar, Baner, Pune', 'https://luma.com/xtuiyzyb', 'https://images.lumacdn.com/uploads/8a/37bae4b6-1d71-4770-9daf-7ac93f41b111.png', 40, 'Founders, aspiring entrepreneurs and innovators with a startup idea.', null, 999, 23, false, null, null, '[{"name":"Ekoham Holistic Wellness","role":"Venue"}]'::jsonb, null, true, 'founders-in-making-pitch-ice-bath-2026-06', '00000000-0000-4000-8000-000000000040', 'Founders in Making — Pitch & Ice Bath', '2026-06-27T05:30:00.000Z', 'pitch_session'),
  ('00000000-0000-4000-9000-000000000015', 'Building a personal brand that feels true to you and still earns trust — frameworks for finding your visual voice and showing up with credibility.', '2026-07-09T14:00:00.000Z', 'Online', null, 'https://luma.com/3e755mkj', 'https://images.lumacdn.com/uploads/6w/03b00d38-dea5-4332-9c41-ac92d04b7ffb.png', null, null, null, 0, 8, true, null, '[{"name":"Sakina Jalal","role":"Founder, Mojo Creatives"}]'::jsonb, null, null, true, 'power-hour-beyond-the-grid-2026-07', '00000000-0000-4000-8000-000000000040', 'BNC Power Hour: Beyond the Grid', '2026-07-09T13:00:00.000Z', 'power_hour'),
  ('00000000-0000-4000-9000-000000000016', 'A morning of guided breathwork, an ice bath and mindful recovery in Koregaon Park, with Ekoham and HS.', '2026-07-26T06:30:00.000Z', 'Palmonas', 'Lane No. 8, Koregaon Park, Pune', 'https://luma.com/1plpxprq', 'https://images.lumacdn.com/uploads/e9/74281aef-36fa-4ebd-ba61-42e26e04239b.jpg', null, null, null, null, 5, false, null, null, '[{"name":"Palmonas","role":"Host venue"},{"name":"Ekoham","role":"Collaborator"},{"name":"HS","role":"Collaborator"}]'::jsonb, null, true, 'icebath-breathwork-palmonas-2026-07', '00000000-0000-4000-8000-000000000040', 'Ice Bath & Breathwork with Palmonas', '2026-07-26T04:30:00.000Z', 'wellness'),
  ('00000000-0000-4000-9000-000000000017', 'Less hype, more implementation: lightning talks on how people use AI every day, an open discussion, and AI speed networking for founders, creators and freelancers.', '2026-08-01T13:30:00.000Z', 'CC&Co — CoCreators And Company', 'Gokhale Business Bay, Kothrud, Pune', 'https://luma.com/73lo0ax5', 'https://images.lumacdn.com/uploads/0l/ee30d92f-c0e0-4130-adbc-c8cda99b812c.png', null, 'Founders, creators, freelancers, professionals, students and AI enthusiasts.', '[{"time":"4:00 PM","item":"Networking over coffee"},{"time":"4:30 PM","item":"Lightning talks — How I use AI every day"},{"time":"5:00 PM","item":"Open discussion: AI for business, creators, freelancers; automation; tools"},{"time":"6:00 PM","item":"AI speed networking: one tool, one problem, one collaboration you want"},{"time":"6:45 PM","item":"Community photo and open networking"}]'::jsonb, 399, 23, false, null, '[{"name":"Isha Ostwal","role":"Founder & CEO, DreamSVin & BNC"},{"name":"Mangesh Shinde","role":"Founder, WillStar Media"},{"name":"Omkar Amble","role":"AI mentor for freelancers"}]'::jsonb, '[{"name":"CC&Co","role":"Venue"}]'::jsonb, null, true, 'lets-talk-ai-pune-2026-08', '00000000-0000-4000-8000-000000000040', 'Let''s Talk AI — not your regular AI meetup', '2026-08-01T10:30:00.000Z', 'workshop'),
  ('00000000-0000-4000-9000-000000000018', 'Where are the next real estate opportunities? A closed-door room for developers, investors and advisors — asset classes, geography and the ₹10 crore question.', '2026-10-06T14:00:00.000Z', 'Dextrus — Peninsula Corporate Park', 'Lower Parel, Mumbai', 'https://luma.com/2ltwf46h', 'https://images.lumacdn.com/uploads/z2/b8f262a9-d5d0-43d0-a4ba-0181ae01cdf9.png', null, 'Developers, investors, real estate entrepreneurs, PropTech founders, advisors and ecosystem partners. Invite only.', '[{"time":"5:00 PM","item":"Arrival and curated networking"},{"time":"5:25 PM","item":"Opening by Isha Ostwal"},{"time":"5:35 PM","item":"Panel: asset classes × geography × investment opportunities"},{"time":"6:20 PM","item":"The ₹10 crore question"},{"time":"6:35 PM","item":"Open table discussion"},{"time":"6:55 PM","item":"Who''s building what + curated connections"}]'::jsonb, 0, 40, false, null, '[{"name":"Dr. Adv. Harshul Savla","role":"Managing Partner, M Realty"},{"name":"Dhaval Upendrakumar","role":"Founder, Nagarsheth Group"},{"name":"Chintan Vasani","role":"Founder Partner, WibesRealty"},{"name":"Isha Ostwal","role":"Moderator · Founder, DreamSVin & BNC"}]'::jsonb, '[{"name":"Dextrus","role":"Venue"}]'::jsonb, null, true, 'real-estate-room-mumbai-2026-10', '00000000-0000-4000-8000-000000000010', 'BNC Real Estate Room — Mumbai Edition', '2026-10-06T11:30:00.000Z', 'industry_room')
